// ── The space ladder — the design system's rungs. Every magnitude in the medium composes
//    from these by name, and a canvas states proportions, and the seed (`SpaceSeed`) is the one
//    number that turns a count into pixels. The numerals themselves are the lattice's
//    (Primitive.swift): one ladder, spelled once, read by every target. ──

import VerificationIsIdentification

// ═══════════════════════════════════════════════════════════════
// THE DYNAMICS MEDIUM: a button over a state file is a rewrite triple, not a
// program. A state file is a form whose slots are `typealias <Slot> = <term>`
// lines, and a rule names one slot, one expected pattern, one replacement
// template. Pressing compares and substitutes: one match or none, and a
// mismatch leaves the file byte-identical. The one applier is in Tools
// (`swift run Tools press <Rule>`), is the same few lines for every domain,
// and no domain logic is ever written as code: a system's behaviour is its
// triples.
//
// The judge is on the edges, not the states: a rule with a variable is a
// generic declaration, so the compiler admits every application at once, and
// every reachable state of a chain is well-typed before the first press. In
// the theory's own axis this is the Law relocated one step further: where
// `HasLaw` identifies a transition law from observed examples, a triple is
// the law PRESENTED by its author, and the build is the gate it must pass.
// ═══════════════════════════════════════════════════════════════

/// What a key may carry: one slot's worth of pressing. A single rule is the
/// base case and a chord of rules is the cons, so a key's bound never grows an
/// arity: any width is nested pairs of this one protocol, the same law every
/// tree in this package obeys.
public protocol Pressable {
    associatedtype Slot   // law:allow — read by RuleKey's slot attribute and by the one applier (Tools press): the medium's reader stands outside the judge
}

/// One rewrite rule: the slot it owns, the pattern it expects, the template it
/// leaves. A rule whose template fails some binding of its
/// pattern's variables refuses to compile on its own line, so a dictionary of
/// rules that builds is a dictionary whose every press is safe. The axes are
/// read by the medium's one applier (Tools press) and by ``RuleKey``'s slot
/// attribute: the reader of a state file's dynamics is outside the module,
/// which is the medium's whole point.
public protocol SlotRule: Pressable {
    associatedtype From   // law:allow — the pattern: compared by the one applier, never inside the module
    associatedtype Into   // law:allow — the template: substituted by the one applier, never inside the module
}

/// The chord's cons: two pressables of the SAME slot under one face. Nesting
/// this one pair reaches any width, and the one-slot bound is on every link of
/// the chain. At any state at most one leaf of a lawful chord matches, so a
/// chord press remains an identification (§S30), whatever its width.
/// This marks a key's term as an instance to carry whole: the key's face
/// spells the full applied term, holes filled, because the press supplies the
/// atom and the atom must travel with the press. A generic rule's key remains
/// bare (its placeholder is spelling, not information), so the two kinds are
/// told apart by statement, never by guessing at a name's tail.
public enum Exactly<Rule: Pressable>: Pressable {
    public typealias Slot = Rule.Slot
}

public enum Chord<
    A: Pressable,
    B: Pressable
>: Pressable
where A.Slot == B.Slot {
    public typealias Slot = A.Slot
}

// ── the term reader: the term's original characters. XML serialization belongs
//    to Vector's text/attribute edge, after any measurement. ──

/// A term's name as text. The SVG reader escapes it at serialization.
public enum TermText<T>: Close {}
extension TermText {
    public static var typeName: String { String(describing: T.self) }
}

import VerificationIsIdentification

/// XML serialization reads characters only at the output edge. Measurement and type
/// spelling keep the original text; composition keeps its already serialized markup.
public enum XMLEscaped<Content: Structure>: Close {}
extension XMLEscaped {
    public static var typeName: String {
        Content.typeName.unicodeScalars.map { character -> String in
            switch character {
            case "&": return "&amp;"
            case "<": return "&lt;"
            case ">": return "&gt;"
            case "\"": return "&quot;"
            case "'": return "&apos;"
            default: return String(character)
            }
        }.joined()
    }
}

/// Time is a rational reading of integer ticks, not integer lattice division.
public enum Seconds<Ticks: Structure, Frequency: Structure>: Close {}
extension Seconds {
    public static var typeName: String {
        precondition(Frequency.count > 0, "Seconds requires a positive frequency")
        return String(Double(Ticks.count) / Double(Frequency.count))
    }
}

// ═══════════════════════════════════════════════════════════════
// VECTOR is SVG as DocumentKit's second medium, the same mechanism Markup.swift
// uses for markdown: every atom is a `Close` read through `typeName`, every combinator is an
// `Open` protocol whose `body` composes atoms, walked by `typeName` into the drawing. SVG is
// text, and `typeName` already generates text: drawing is the same act as rendering a page,
// not a second one. The geometry is OURS: a `viewBox` fixes the coordinate system and aspect
// ratio, so embedding as an `<img>` (DocC's choice) scales both axes together,
// deterministically. The walls this file's laws name for markdown (§S15 no column width,
// §S19 no visible weight, §S21 fixed image margins) are walls of THAT medium, not this one.
//
// Vocabulary is exactly what today's artifacts need (§S8, no general solver), and it is
// three languages of one geometry: the DIVIDED AXIS (a row or column hands each member its
// slice and the remainder derives), the SPANS (leaves drawn into the slice they are handed),
// and the PEN (a path as constrained motion: straight until a named line, so corners
// derive). Every number a drawing speaks is a rung of the dictionary (Design.swift) or a
// magnitude of the lattice, read through `Tally`, `SpanPx`, `Halfway`, `Under`, and the stated
// remainders are named holes (text baselines, glyph art), each argued in place.
// Per-instance content (a glyph's path data, a line's text) is a `Structure` hole, exactly
// like `Symbol`'s target or `TableCell`'s content.
// ═══════════════════════════════════════════════════════════════

// THE CANVAS CONTRACT — what the medium guarantees, and what it does not.
//
// GUARANTEED. A Canvas fixes a coordinate space of its own: viewBox W×H is a pixel
// grid that belongs to the composition. Inside it, the composition's geometry is
// its own, and the host cannot reach in: no margin, no centering, no theme
// rule moves anything within the viewBox. The host may scale the canvas ONLY
// as a whole, uniformly: the aspect is preserved, so a known width fixes the
// height. Nothing drifts.
//
// NOT GUARANTEED. The absolute on-screen size: markdown offers no pixel pin,
// so the canvas renders at container width. Right SHAPE always, exact screen
// pixels never promised. Text metrics: glyph width is the platform font's, and
// the craft is a fixed font-family and generous boxes (§S15's discipline:
// state the box, never compute the fit).
// ═══════════════════════════════════════════════════════════════

// GATE TIERS. Compile gate: an illegal type does not build (`Legible`,
// `WithinBounds`, the strongest form). Generation gate: an illegal VALUE
// stops `generate` with a named precondition (`BudgetedLabel`), weaker,
// still before anything ships. Host gate: what only the browser decides
// (hover, theme), declared, never trusted with correctness.
// ═══════════════════════════════════════════════════════════════

/// This marks a canvas that shows its source. Opting in costs nothing beyond this empty
/// conformance: the composition a conforming canvas's `body` shows is ALREADY the exact type its
/// `@StructureBuilder` folded (a left-nested `Paired` chain), so a reader can read that
/// SAME type back through `String(reflecting: Body.self)` and print it. The reader is
/// VectorDemo's decompiler, a driver-level, value-level concern. This medium only carries the
/// marker and, per canvas, the small `{ }` chip built from existing atoms (`GlyphRect`,
/// `Label`, `Linked`).
/// Nothing here can drift from what compiled, because nothing here is a second copy of it.
public protocol SelfShowing {}

/// This is several drawn pieces, composed through `body` into one: the SVG-medium counterpart of
/// `Fragment` (Organization/View/Screen.swift), local here since DocumentKit does not depend on
/// Organization. A canvas's `Content` hole is usually one of these.
public protocol Group: Open {}

/// This is the SVG root, like `Screen`/`Reference`, but the medium is source text, not markdown.
