        <defs>
        <marker id="\(XMLEscaped<ArrowHeadName>.typeName)" markerWidth="9" markerHeight="9" refX="5" refY="3" orient="auto">
        <path d="M0,0 L6,3 L0,6 Z" fill="\(XMLEscaped<TextSecondary>.typeName)"/>
