extension SpanVariant: Spanning {
    public static func rendered<
        X: Frac & Structure,
        W: Frac & Structure
    >(
        atX x: X.Type,
        width w: W.Type
    ) -> String {
        "<g class=\"vi-variant\" data-vi-owner=\"\(XMLEscaped<Owner>.typeName)\" data-vi-at=\"\(XMLEscaped<Position>.typeName)\""
