            Dimmer<Dimmer<Dimmer<Brighter<Brighter<Brighter<Dimmer<Dimmer<Settled>>>>>>>>,
            Dimmer<Dimmer<Dimmer<Brighter<Brighter<Brighter<Brighter<Dimmer<Settled>>>>>>>>
        >.typeName
    }
}
