    public typealias YShare = Plus<Twice<Twice<Unit>>, Plus<Twice<Unit>, Unit>>
    public typealias ZShare = Unit
    public static var typeName: String { "srgb-red" }
}

/// The sRGB green primary: 0.3576, 0.7152, 0.1192.
