public enum UntilY<
    Prev: Pen,
    Line: Structure
>: Close {}
extension UntilY: Pen {
    public typealias AtX = Prev.AtX
    public typealias AtY = Line
    public static var typeName: String {
        "\(XMLEscaped<Prev>.typeName) L\(XMLEscaped<SpanPx<Prev.AtX>>.typeName),\(Line.count)"
