        let measured: (Substring) -> Int = { text in
            let total = text.unicodeScalars.reduce(0) { sum, scalar in
                sum + (advances[Int(scalar.value)] ?? fallback)
            }
            return (total * size + units - 1) / units
        }
        var lines: [Substring] = []
        var line = Substring("")
        for word in Content.typeName.split(separator: " ") {
