                case "'": return "&apos;"
                default: return String(character)
                }
            }.joined()
            return "<text x=\"\(XMLEscaped<SpanPx<X>>.typeName)\" y=\"\(base + pitch * index)\" text-anchor=\"start\" "
                + "fill=\"\(XMLEscaped<FillColor>.typeName)\" font-weight=\"\(XMLEscaped<Weight>.typeName)\" "
